mapper.select:
SELECT id, type, label, lng, lat, version, updated_at, properties
FROM network_elements
WHERE location && ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326)
  AND lng >= #{west} AND lng < #{east}
  AND lat > #{south} AND lat <= #{north}
  AND (#{types} IS NULL OR type = ANY(#{types}::text[]))
  AND (#{propFilter} IS NULL OR properties @> #{propFilter}::jsonb)
ORDER BY id
LIMIT #{limit}

SELECT id
FROM network_elements
WHERE location && ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326)
  AND lng >= #{west} AND lng < #{east}
  AND lat > #{south} AND lat <= #{north}
  AND (#{types} IS NULL OR type = ANY(#{types}::text[]))
  AND (#{propFilter} IS NULL OR properties @> #{propFilter}::jsonb)
ORDER BY id
LIMIT #{limit}

SELECT id, lng, lat FROM network_elements WHERE id IN
#{id}
ORDER BY id
